def write(root: Path, rel: str, txt: str):
    p = root/rel; p.parent.mkdir(parents=True, exist_ok=True); p.write_text(txt, encoding='utf-8')

def run(a, cwd=None, check=False):
    subprocess.run(a, cwd=cwd, check=check)

def find_root(seed: Path) -> Path:
    p = seed
    for _ in range(12):
        if (p/'.git').exists(): return p
        if p.parent==p: break
        p = p.parent
    return seed

def main():
    root = find_root(Path(__file__).resolve())
    for rel, txt in FILES.items():
        write(root, rel, txt)
    try: run(['git','checkout','-B','step/PA-340-mobile-console-and-jobs'], root)
    except Exception: pass
    run(['git','add','-A'], root)
    run(['git','commit','-m','PA-340: mobile console (/app), jobs API (/api/jobs), ops pages (/ops), Edge opener, smokes'], root)
    run(['git','push','-u','origin','step/PA-340-mobile-console-and-jobs'], root)
    print('PA-340 applied.')
    print('Usage:')
    print('  pwsh tools\\ps1\\run_control_server.ps1   # starts Flask with imported blueprints')
    print('  pwsh tools\\ps1\\open_mobile.ps1          # opens /app/ in Edge')
if __name__=='__main__':
    main()